/* =======================
   Booking form field alignment (horizontal alignment)
   ======================= */
.booking-form-row-fields {
  display: flex;
  flex-direction: row;
  gap: 18px;
  align-items: flex-end;
  flex-wrap: wrap;
}
.booking-form-row-fields label {
  display: flex;
  flex-direction: column;
  min-width: 140px;
  margin: 0;
  flex: 1 1 120px;
}
@media (max-width: 700px) {
  .booking-form-row-fields {
    flex-direction: column;
    gap: 13px;
    align-items: stretch;
  }
  .booking-form-row-fields label {
    min-width: 90px;
    flex: 1 1 90px;
  }
}
